import re
import logging
from typing import List, Dict, Any
from flask import Flask, request, jsonify

logger = logging.getLogger(__name__)

class AnalysisService:
    """服务类：分析访谈记录，提取特征和痛点"""

    # 预定义关键词（MVP 简单实现）
    FEATURE_KEYWORDS = ["功能", "速度快", "易用", "稳定", "安全", "集成", "效率"]
    PAIN_KEYWORDS = ["难用", "慢", "贵", "复杂", "不稳定", "不安全", "不方便"]

    @staticmethod
    def analyze(records: List[Dict[str, Any]]) -> Dict[str, Any]:
        """
        分析访谈记录列表，提取去重排序后的特征词和痛点词，统计受访人数

        :param records: 包含 interviewee, company, content, timestamp 的字典列表
        :return: AnalysisSummary 字典
        """
        features = []
        pains = []
        interviewees = set()

        for record in records:
            content = record.get("content", "")
            interviewee = record.get("interviewee", "")
            interviewees.add(interviewee)

            # 提取特征：简单匹配关键词
            for kw in AnalysisService.FEATURE_KEYWORDS:
                if kw in content:
                    features.append(kw)
            # 提取痛点
            for kw in AnalysisService.PAIN_KEYWORDS:
                if kw in content:
                    pains.append(kw)

        # 去重并排序
        features = sorted(set(features))
        pains = sorted(set(pains))

        return {
            "key_features": features,
            "pain_points": pains,
            "interviewee_count": len(interviewees)
        }


def create_app() -> Flask:
    """创建 Flask 应用并注册 /analyze 路由"""
    app = Flask(__name__)

    @app.route("/analyze", methods=["POST"])
    def analyze():
        data = request.get_json(silent=True)
        if data is None:
            return jsonify({"error": "Invalid JSON"}), 400

        if not isinstance(data, list):
            return jsonify({"error": "Input must be a list"}), 400

        if len(data) == 0:
            return jsonify({"error": "List is empty"}), 400

        # 校验每条记录
        for i, record in enumerate(data):
            if not isinstance(record, dict):
                return jsonify({"error": f"Record {i} is not a dict"}), 422
            required = ["interviewee", "company", "content", "timestamp"]
            for field in required:
                if field not in record:
                    return jsonify({"error": f"Record {i} missing field: {field}"}), 422
                if not isinstance(record[field], str):
                    return jsonify({"error": f"Record {i} field {field} must be string"}), 422

        try:
            result = AnalysisService.analyze(data)
            return jsonify(result), 200
        except Exception as e:
            logger.exception("Internal error during analysis")
            return jsonify({"error": "Internal server error"}), 500

    return app


if __name__ == "__main__":
    app = create_app()
    app.run(debug=True)

