import logging
from typing import Dict, List, Union

logger = logging.getLogger(__name__)


class ValidationResult:
    """Result of document validation."""
    def __init__(self, is_valid: bool, missing_sections: List[str], details: Dict[str, bool]):
        self.is_valid = is_valid
        self.missing_sections = missing_sections
        self.details = details

    def to_dict(self) -> Dict:
        return {
            "is_valid": self.is_valid,
            "missing_sections": self.missing_sections,
            "details": self.details
        }


REQUIRED_SECTIONS = ["市场机会", "目标市场", "竞品分析"]


def validate_document(content: Union[str, Dict]) -> ValidationResult:
    """
    Validate that a document contains required market research sections.

    Args:
        content: Document content as a string or a dictionary with a 'text' key.

    Returns:
        ValidationResult with validation status and missing sections.

    Raises:
        ValueError: If input is empty, not a string/dict, or missing 'text' key.
        RuntimeError: For unexpected internal errors.
    """
    try:
        if not content:
            raise ValueError("Input content is empty")

        if isinstance(content, dict):
            if "text" not in content:
                raise ValueError("Dictionary must contain 'text' key")
            text = content["text"]
        elif isinstance(content, str):
            text = content
        else:
            raise ValueError(f"Unsupported type: {type(content)}. Expected str or dict.")

        if not isinstance(text, str):
            raise ValueError("Extracted text is not a string")

        details = {}
        missing = []
        for section in REQUIRED_SECTIONS:
            present = section in text
            details[section] = present
            if not present:
                missing.append(section)

        is_valid = len(missing) == 0
        return ValidationResult(is_valid=is_valid, missing_sections=missing, details=details)

    except ValueError:
        raise
    except Exception as e:
        logger.error(f"Unexpected error during validation: {e}")
        raise RuntimeError("Internal validation error") from e

