import logging
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, validator

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


class PromptRequest(BaseModel):
    user_input: str = Field(..., min_length=1, max_length=500)
    scene: str
    params: Dict[str, Any] = Field(default_factory=dict)

    @validator('scene')
    def scene_must_be_allowed(cls, v):
        allowed = {'summary', 'translate', 'qa'}
        if v not in allowed:
            raise ValueError(f'Scene "{v}" not allowed. Choose from {allowed}')
        return v


class PromptResponse(BaseModel):
    generated_text: str
    validation_errors: List[str] = Field(default_factory=list)


class PromptTemplate(BaseModel):
    scene: str
    template: str
    rules: Dict[str, Any] = Field(default_factory=dict)


class LLMClient:
    """Mock LLM client for demonstration."""
    def generate(self, prompt: str) -> str:
        logger.info("Calling LLM with prompt: %s", prompt[:50])
        # Simulate LLM response
        return f"Generated response for: {prompt[:30]}..."


class PromptService:
    """Service to handle prompt generation and validation."""

    def __init__(self, llm_client: Optional[LLMClient] = None):
        self.llm_client = llm_client or LLMClient()
        self.templates: Dict[str, PromptTemplate] = {
            'summary': PromptTemplate(
                scene='summary',
                template='Summarize the following text: {user_input}',
                rules={'max_words': 100}
            ),
            'translate': PromptTemplate(
                scene='translate',
                template='Translate to {target_lang}: {user_input}',
                rules={'max_words': 200}
            ),
            'qa': PromptTemplate(
                scene='qa',
                template='Answer the question: {user_input}',
                rules={'max_words': 150}
            ),
        }

    def _assemble_prompt(self, template: PromptTemplate, user_input: str, params: Dict[str, Any]) -> str:
        """Assemble the final prompt by filling the template."""
        try:
            return template.template.format(user_input=user_input, **params)
        except KeyError as e:
            logger.error("Missing parameter in template: %s", e)
            raise ValueError(f"Missing parameter: {e}") from e

    def _validate_output(self, text: str, rules: Dict[str, Any]) -> List[str]:
        """Validate generated text against rules (e.g., max words)."""
        errors = []
        max_words = rules.get('max_words')
        if max_words and len(text.split()) > max_words:
            errors.append(f"Exceeded max words limit of {max_words}")
        return errors

    def generate(self, request: PromptRequest) -> PromptResponse:
        """Main method: validate input, load template, call LLM, validate output."""
        logger.info("Processing request for scene: %s", request.scene)
        template = self.templates[request.scene]
        prompt = self._assemble_prompt(template, request.user_input, request.params)
        try:
            generated_text = self.llm_client.generate(prompt)
        except Exception as e:
            logger.error("LLM call failed: %s", e)
            raise RuntimeError("LLM service unavailable") from e
        validation_errors = self._validate_output(generated_text, template.rules)
        return PromptResponse(generated_text=generated_text, validation_errors=validation_errors)

"""
A simple command-line todo list manager.

Usage:
    python todo_cli.py add "Buy groceries"
    python todo_cli.py list
    python todo_cli.py done 1
"""

import sys
import logging
from typing import List, Optional

logging.basicConfig(level=logging.INFO, format='%(message)s')
logger = logging.getLogger(__name__)


class Task:
    """Represents a single task."""
    def __init__(self, task_id: int, title: str, completed: bool = False) -> None:
        self.id = task_id
        self.title = title
        self.completed = completed

    def __repr__(self) -> str:
        status = "✓" if self.completed else "✗"
        return f"{self.id}. [{status}] {self.title}"


class TodoManager:
    """Manages a list of tasks in memory."""
    def __init__(self) -> None:
        self.tasks: List[Task] = []
        self._next_id = 1

    def add_task(self, title: str) -> Task:
        """Add a new task with the given title."""
        task = Task(self._next_id, title)
        self.tasks.append(task)
        self._next_id += 1
        logger.info(f"Added task: {task}")
        return task

    def list_tasks(self) -> List[Task]:
        """Return all tasks."""
        return self.tasks

    def complete_task(self, task_id: int) -> Optional[Task]:
        """Mark a task as completed by its ID. Returns the task or None if not found."""
        for task in self.tasks:
            if task.id == task_id:
                task.completed = True
                logger.info(f"Completed task: {task}")
                return task
        return None


def print_usage() -> None:
    """Print usage instructions."""
    logger.error("Usage: python todo_cli.py <add|list|done> [arguments]")


def main(argv: Optional[List[str]] = None) -> None:
    """
    Parse command-line arguments and execute the corresponding action.

    Args:
        argv: List of command-line arguments (defaults to sys.argv[1:]).
    """
    if argv is None:
        argv = sys.argv[1:]

    if len(argv) < 1:
        print_usage()
        sys.exit(1)

    command = argv[0].lower()
    manager = TodoManager()

    try:
        if command == "add":
            if len(argv) < 2:
                logger.error("Error: Missing task title.")
                sys.exit(1)
            title = argv[1]
            manager.add_task(title)

        elif command == "list":
            tasks = manager.list_tasks()
            if not tasks:
                logger.info("No tasks found.")
            else:
                for task in tasks:
                    logger.info(task)

        elif command == "done":
            if len(argv) < 2:
                logger.error("Error: Missing task ID.")
                sys.exit(1)
            try:
                task_id = int(argv[1])
            except ValueError:
                logger.error("Error: Task ID must be an integer.")
                sys.exit(1)
            task = manager.complete_task(task_id)
            if task is None:
                logger.error(f"Error: Task with ID {task_id} not found.")
                sys.exit(1)

        else:
            print_usage()
            sys.exit(1)

    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
